import type { Id } from "../../src/store/id.ts";
import type { Declaration, Given, HolonOf, Space } from "../../src/interface/component.ts";
import type { By, Expression } from "../../src/engine/expression.ts";
import type { ComponentBody, ExpressionBody, Ref } from "./bodies.ts";
import { h } from "./jsx.ts";
import { partsOf, partWords, titleOf, together, type Parts } from "./parts.ts";
import { axisWords } from "./words.ts";

// A search: where one stands, said by what it means, and what one may go to
// from there, found as one types. Given a way of looking, it says its parts,
// each a meaning that can be let go; given a holon, what it is and what it
// is called. Typing searches the field: the holons that say the words, the
// types they name, the ways of grouping; each found is a place, pressed to
// go there, or a part, pressed to narrow where one stands by it. Before
// anything is typed it offers what is near: the favorites its holders
// offer, the ways out of where it stands, and, given the component a place
// is drawn by, what can be done there: look there, look with another
// component, set what that component takes and nothing gave it, place it
// on the favorites or take it off.
//
// It acts on nothing. Each thing it offers is a press that says where it
// leads, as every location does, and rises to the mount that holds it.

export const declared = {
  title: "Search",
  says: "Where one stands, said by what it means, and a search of the field from there: the holons that say the words, their types and groupings, and what can be done here, each a press that rises to the mount.",
  takes: [],
  kinds: ["full", "face"],
  argument: "selection",
  settings: {
    drawn: {
      says: "The component the place is drawn by where it was pressed, whose settings it offers to set.",
      shape: "ref",
      optional: true,
    },
    focused: {
      says: "Whether it takes the focus as it is drawn, as where it was asked for.",
      shape: "boolean",
      optional: true,
    },
  },
  reads: ["gather", "holon", "instances", "name"],
} satisfies Declaration;

interface SearchSettings {
  drawn?: Ref;
  focused?: boolean;
}

// What a press leads to: a place, by its holons, drawn as the mount finds
// or by a component; a way of looking; or what the mount offers.
type Lead =
  | { location: Id[]; component?: Id }
  | { expression: Expression; title: string }
  | { offer: Record<string, unknown> };

interface Found {
  label: string;
  meta: string;
  lead: Lead;
  // Other ways to take what was found, each a part to narrow by.
  also?: { label: string; lead: Lead }[];
}

const shown = 8;

export default async function draw(given: Given<never, SearchSettings>, space: Space) {
  const titled = async (id: Id) => String((await space.holon(id))?.body.title ?? id);
  const ids = given.list ?? (given.holon ? [given.holon.id] : []);
  const one = given.holon as HolonOf<Record<string, unknown>> | undefined;

  const [expressionType, componentType, full] = await Promise.all(
    ["expression", "component", "full"].map((name) => space.read({ name })),
  );
  const standing: Parts | undefined =
    one && expressionType && one.instance.includes(expressionType)
      ? partsOf((one.body as unknown as ExpressionBody).gathers)
      : undefined;

  // Where one stands, narrowed by one more part: what is grouped stays
  // grouped; from a holon, from everything, grouped by what splits it best.
  const narrowed = async (part: Expression): Promise<Lead> => {
    const parts = standing
      ? { ...standing, parts: [...standing.parts, part] }
      : { parts: [part], by: "strongest" as By };
    return toward(parts);
  };
  const toward = async (parts: Parts): Promise<Lead> => ({
    expression: together(parts),
    title: await titleOf(together(parts), titled),
  });

  // Where one stands, each part a meaning drawn as a chip, pressed to let
  // it go; a holon, by its types, each a way to look at its kind, and its
  // title.
  const chips = standing
    ? [
        ...(await Promise.all(
          standing.parts.map(async (part, i) =>
            chip(
              await partWords(part, titled),
              await toward({ ...standing, parts: standing.parts.filter((_, j) => j !== i) }),
            ),
          ),
        )),
        ...(standing.by ? [chip(axisWords[standing.by], await toward({ parts: standing.parts }))] : []),
      ]
    : one
      ? [
          ...(await Promise.all(
            one.instance.map(async (type) =>
              place(
                await titled(type),
                await toward({ parts: [{ instances: { $ref: type } }], by: "strongest" }),
              ),
            ),
          )),
          <span class="part here">{String(one.body.title ?? one.id)}</span>,
        ]
      : [<span class="part here">{ids.length === 1 ? "one holon" : `${ids.length} holons`}</span>];

  const favorites = ((given.offered.favorites ?? []) as Ref[]).map(({ $ref }) => $ref);
  const settings = given.settings;

  // What is near, before anything is typed.
  const near = async (): Promise<Found[]> => {
    const found: Found[] = [];
    if (settings.drawn) {
      const drawn = await space.holon<ComponentBody>(settings.drawn.$ref);
      found.push({ label: "Look here", meta: "go", lead: { location: ids } });
      for (const other of await drawers())
        if (other.id !== drawn?.id)
          found.push({
            label: `Look here with ${other.body.title}`,
            meta: "component",
            lead: { location: ids, component: other.id },
          });
      for (const [key, setting] of Object.entries(
        (drawn?.body.settings ?? {}) as Record<string, { says: string; shape: unknown }>,
      ))
        if (setting.shape === "boolean") {
          const now = given.offered[key] === true;
          found.push({
            label: `${capital(key)}: ${now ? "on, turn off" : "off, turn on"}`,
            meta: `${drawn!.body.title}: ${setting.says}`,
            lead: { offer: { [key]: !now } },
          });
        }
      if (one) {
        const placed = favorites.includes(one.id);
        found.push({
          label: placed ? "Take off the favorites" : "Place on the favorites",
          meta: "favorites",
          lead: {
            offer: {
              favorites: (placed ? favorites.filter((id) => id !== one.id) : [...favorites, one.id]).map(
                ($ref) => ({ $ref }),
              ),
            },
          },
        });
      }
    }
    for (const id of favorites)
      if (id !== one?.id) found.push({ label: await titled(id), meta: "favorite", lead: { location: [id] } });
    if (one && !standing) {
      const title = String(one.body.title ?? one.id);
      found.push({
        label: `What ${title} holds`,
        meta: "a way out",
        lead: await narrowed({ from: { $ref: one.id } }),
      });
      found.push({
        label: `What points at ${title}`,
        meta: "a way out",
        lead: await narrowed({ pointing: { $ref: one.id } }),
      });
    }
    if (standing)
      for (const axis of ["strongest", "type", "holder", "store"] as By[])
        if (axis !== standing.by)
          found.push({
            label: `Group ${axisWords[axis]}`,
            meta: "grouping",
            lead: await toward({ ...standing, by: axis }),
          });
    return found;
  };

  // The components that can draw this place in full.
  const drawers = async () => {
    if (!componentType || !full) return [];
    const all = await Promise.all(
      (await space.read({ instances: componentType })).map((id) => space.holon<ComponentBody>(id)),
    );
    const fits = (argument = "holon") =>
      argument === "selection" || argument === (ids.length === 1 ? "holon" : "list");
    return all.filter(
      (component): component is HolonOf<ComponentBody> =>
        !!component &&
        component.body.kinds.some(({ $ref }) => $ref === full) &&
        fits(component.body.argument) &&
        (component.body.takes.length === 0 ||
          (!!one && component.body.takes.some(({ $ref }) => one.instance.includes($ref)))),
    );
  };

  // What the words find: the holons that say them, as a part to narrow by;
  // the types named by them, to narrow to; the ways of grouping they name;
  // and the holons that say them, those whose title says them first, each
  // a place to go, or a part, what it holds or what points at it.
  const search = async (text: string): Promise<Found[]> => {
    const words = text.trim();
    const lower = words.toLocaleLowerCase();
    const says = (label: string) =>
      lower.split(/\s+/).every((word) => label.toLocaleLowerCase().includes(word));
    const found: Found[] = [
      { label: `Saying “${words}”`, meta: "narrow by the words", lead: await narrowed({ match: words }) },
    ];

    const types = await Promise.all(
      (await space.read({ gather: { types: true } })).map((id) => space.holon(id)),
    );
    for (const type of types)
      if (type && says(String(type.body.title)))
        found.push({
          label: `Only ${type.body.title}`,
          meta: "narrow to a type",
          lead: await narrowed({ instances: { $ref: type.id } }),
        });

    for (const axis of ["strongest", "type", "holder", "store"] as By[])
      if (axis !== standing?.by && says(`group ${axisWords[axis]}`))
        found.push({
          label: `Group ${axisWords[axis]}`,
          meta: "grouping",
          lead: await toward({ ...(standing ?? { parts: [] }), by: axis }),
        });

    const matched = await space.read({ gather: { match: words } });
    const read = (await Promise.all(matched.slice(0, 120).map((id) => space.holon(id)))).filter(
      (holon): holon is NonNullable<typeof holon> => !!holon,
    );
    const rank = (title: string) => {
      const said = title.toLocaleLowerCase();
      return said.startsWith(lower) ? 0 : says(title) ? 1 : 2;
    };
    const ranked = read
      .map((holon) => ({ holon, title: String(holon.body.title ?? holon.id) }))
      .sort((a, b) => rank(a.title) - rank(b.title));
    for (const { holon, title } of ranked.slice(0, shown))
      found.push({
        label: title,
        meta: (await Promise.all(holon.instance.map(titled))).join(", "),
        lead: { location: [holon.id] },
        also: [
          { label: "what it holds", lead: await narrowed({ from: { $ref: holon.id } }) },
          { label: "what points at it", lead: await narrowed({ pointing: { $ref: holon.id } }) },
        ],
      });
    if (matched.length > shown)
      found.push({
        label: `All ${matched.length} saying “${words}”`,
        meta: "narrow by the words",
        lead: found[0]!.lead,
      });

    const nearby = (await near()).filter(({ label }) => says(label));
    return [...nearby, ...found];
  };

  const input = (
    <input
      class="search-input"
      type="search"
      role="combobox"
      aria-autocomplete="list"
      aria-expanded="true"
      spellcheck="false"
      placeholder={
        standing || !one ? "Type to search, or to narrow what you see" : "Type to search the field"
      }
    />
  ) as HTMLInputElement;
  const listed = (<ul class="search-found" role="listbox" />) as HTMLElement;
  const element = (
    <div class={settings.focused ? "search focused" : "search"}>
      <div class="search-field">
        {chips}
        {input}
      </div>
      {listed}
    </div>
  ) as HTMLElement;

  // What was found, each a row: pressed whole to go where it leads, or by
  // one of the other ways to take it. The first is where Enter goes.
  let active = 0;
  const rows = () => [...listed.querySelectorAll<HTMLElement>(".found")];
  const mark = (at: number) => {
    const all = rows();
    active = all.length ? (at + all.length) % all.length : 0;
    all.forEach((row, i) => row.classList.toggle("active", i === active));
    all[active]?.scrollIntoView({ block: "nearest" });
  };
  const show = (found: Found[]) => {
    listed.replaceChildren(
      ...found.map(({ label, meta, lead, also }) => (
        <li class="found" role="option">
          {press(lead, <span class="found-label">{label}</span>, <span class="meta">{meta}</span>)}
          {also && <span class="found-also">{also.map(({ label, lead }) => press(lead, label))}</span>}
        </li>
      )),
    );
    mark(0);
  };

  let asked = 0;
  const ask = async () => {
    const turn = ++asked;
    const text = input.value;
    const found = text.trim() ? await search(text) : await near();
    if (turn === asked) show(found);
  };
  input.addEventListener("input", () => void ask().catch((error: unknown) => console.error(error)));
  input.addEventListener("keydown", (event) => {
    if (event.key === "ArrowDown") return (event.preventDefault(), mark(active + 1));
    if (event.key === "ArrowUp") return (event.preventDefault(), mark(active - 1));
    if (event.key === "Enter") {
      event.preventDefault();
      return rows()[active]?.querySelector<HTMLElement>(".lead")?.click();
    }
    // Letting go of the last part, as a word is let go.
    if (event.key === "Backspace" && input.value === "")
      [...element.querySelectorAll<HTMLElement>(".let-go")].at(-1)?.click();
  });

  show(await near());
  if (settings.focused) setTimeout(() => input.focus());
  return element;
}

// A press that leads somewhere.
function press(lead: Lead, ...children: unknown[]) {
  return (
    <button type="button" class="lead" {...said(lead)}>
      {children}
    </button>
  );
}

// A part of where one stands, pressed to let it go.
function chip(label: string, without: Lead) {
  return (
    <span class="part">
      {label}
      <button type="button" class="let-go" aria-label={`Let go of ${label}`} {...said(without)}>
        ×
      </button>
    </span>
  );
}

// A place where one stands is reached from, pressed to go there.
function place(label: string, lead: Lead) {
  return (
    <button type="button" class="part" {...said(lead)}>
      {label}
    </button>
  );
}

// Where a press leads, said as the mount reads it.
function said(lead: Lead) {
  if ("expression" in lead)
    return { "data-expression": JSON.stringify(lead.expression), "data-title": lead.title };
  if ("offer" in lead) return { "data-offer": JSON.stringify(lead.offer) };
  return {
    "data-location": JSON.stringify(lead.location),
    ...(lead.component ? { "data-calls": lead.component } : {}),
  };
}

const capital = (word: string) => word.charAt(0).toUpperCase() + word.slice(1);
